function FeedCard({ post, user, onLike, onComment, onSave, onAuth }: { post: FeedPost; user: User | null; onLike: (post: FeedPost) => void; onComment: (post: FeedPost, body: string) => Promise<void>; onSave: (post: FeedPost, saved: boolean) => Promise<void>; onAuth: () => void }) {
  const activity = post.activity;
  const [commenting, setCommenting] = useState(false);
  const [comment, setComment] = useState("");
  const [saved, setSaved] = useState(false);
  return <article className="feed-card"><header><div className="avatar-initial">{initials(post.profile?.full_name)}</div><div><strong>{post.profile?.full_name ?? "Aventureiro SELVA+"}</strong><small>@{post.profile?.username ?? "aventureiro"} · {new Date(post.created_at).toLocaleDateString("pt-BR")}</small></div></header><div className="feed-copy"><h2>{post.title ?? activity?.title ?? "Nova aventura"}</h2>{post.body ? <p>{post.body}</p> : null}</div>{post.photos[0]?.signed_url ? <Image unoptimized className="feed-photo" src={post.photos[0].signed_url} width={1200} height={800} alt="Foto da aventura" /> : activity?.route_geojson?.coordinates.length ? <ExploreMap compact route={activity.route_geojson.coordinates} /> : null}{activity ? <div className="feed-metrics"><div><strong>{(Number(activity.distance_m) / 1000).toFixed(1)} km</strong><span>Distância</span></div><div><strong>{formatCompactTime(activity.duration_seconds)}</strong><span>Tempo</span></div><div><strong>+{Math.round(Number(activity.elevation_gain_m))} m</strong><span>Elevação</span></div></div> : null}<footer><button className={post.liked_by_me ? "liked" : ""} onClick={() => user ? onLike(post) : onAuth()}><Heart size={18} fill={post.liked_by_me ? "currentColor" : "none"} /> {post.likes}</button><button onClick={() => user ? setCommenting((value) => !value) : onAuth()}><MessageCircle size={18} /> {post.comments}</button><button className={saved ? "liked" : ""} onClick={() => { if (!user) { onAuth(); return; } const next = !saved; setSaved(next); void onSave(post, next).catch(() => setSaved(!next)); }}><Bookmark size={18} fill={saved ? "currentColor" : "none"} /> {saved ? "Salvo" : "Salvar"}</button></footer>{commenting ? <form className="comment-composer" onSubmit={(event) => { event.preventDefault(); if (!comment.trim()) return; void onComment(post, comment.trim()).then(() => { setComment(""); setCommenting(false); }); }}><input value={comment} onChange={(event) => setComment(event.target.value)} maxLength={2000} autoFocus placeholder="Escreva um comentário respeitoso…" /><button aria-label="Enviar comentário"><Send size={17} /></button></form> : null}</article>;
}

